def solve(target: float, ks: list[float], h: float, fraction: float) -> tuple[list[float], list[float]]:
    inputs = []
    times = []
    for k in ks:
        u = k * target
        inputs.append(u)
        a = 0.0
        step = 0
        while a < fraction * target:
            a += h * (u - k * a)
            step += 1
        times.append(step * h)
    return (inputs, times)

