def solve(u: float, k: float, A0: float, hs: list[float], steps: int) -> tuple[list[float], list[float]]:
    first = []
    minimum = []
    for h in hs:
        a = A0
        low = a
        for i in range(steps):
            a += h * (u - k * a)
            low = min(low, a)
            if i == 0:
                first.append(a)
        minimum.append(low)
    return (first, minimum)

