import math

def solve(u: float, k: float, A0: float, end: float, start_h: float, tol: float) -> tuple[float, int, float]:
    u, k, a0 = (u, k, A0)
    h = start_h
    for _ in range(13):
        n = round(end / h)
        a = a0
        error = 0.0
        for i in range(1, n + 1):
            a += h * (u - k * a)
            t = i * h
            ref = a0 + u * t if k == 0 else a0 * math.exp(-k * t) - u / k * math.expm1(-k * t)
            error = max(error, abs(a - ref))
        if error < tol:
            return (h, n, error)
        h /= 2

