import math

def solve(bounds: list[float], rates: list[float], k: float, A0: float) -> tuple[float, float]:
    a = A0
    total = 0.0
    k = k
    for left, right, u in zip(bounds[:-1], bounds[1:], rates):
        h = right - left
        total += u * h
        a = a + u * h if k == 0 else a * math.exp(-k * h) - u / k * math.expm1(-k * h)
    return (total, a)
